    val dates = remember(isLast7Days) {
        if (isLast7Days) {
            (6 downTo 0).map { LocalDate.now().minusDays(it.toLong()) }
        } else {
            val monday = LocalDate.now().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY))
            (0..6).map { monday.plusDays(it.toLong()) }
        }
