                            .fillMaxHeight()
                            .weight(1f),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Bottom
                    ) {
                        if (data.value > 0) {
                            Text(
                                text = if (data.value % 1.0 == 0.0) data.value.toInt()
                                    .toString() else data.value.toString(),
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(6.dp))
                        }
                        if (animatedFraction > 0f) {
                            Box(
                                modifier = Modifier
                                    .width(28.dp)
                                    .fillMaxHeight(animatedFraction)
                                    .background(
                                        color = if (isExpense) errorColor else primaryColor,
                                        shape = RoundedCornerShape(topStart = 6.dp, topEnd = 6.dp)
                                    )
                            )
                        } else {
                            Box(
                                modifier = Modifier
                                    .width(28.dp)
                                    .height(0.dp)
                            )
                        }
                    }
                }
            }
            Spacer(modifier = Modifier.height(12.dp))
            // Labels
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                chartData.forEach { data ->
                    Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.Center) {
                        Text(text = data.label, fontSize = 12.sp, color = Color.Gray)
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(48.dp))

        // Custom Summary Line
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            horizontalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Column(
                modifier = Modifier
                    .weight(1f)
                    .background(surfaceVariant, RoundedCornerShape(12.dp))
                    .padding(16.dp)
            ) {
                Text(
                    text = if (isExpense) "总支出" else "总收入",
                    fontSize = 14.sp,
                    color = Color.Gray
                )
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = String.format(Locale.getDefault(), "%.2f", total),
                    fontSize = 24.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }
            Column(
                modifier = Modifier
                    .weight(1f)
                    .background(surfaceVariant, RoundedCornerShape(12.dp))
                    .padding(16.dp)
            ) {
                Text(
                    text = if (isExpense) "日均支出" else "日均收入",
                    fontSize = 14.sp,
                    color = Color.Gray
                )
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = String.format(Locale.getDefault(), "%.2f", avg),
                    fontSize = 24.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }
        }
    }
}

@Composable
fun MonthlyStatisticView(viewModel: StatisticPage_VM = hiltViewModel()) {
    val allBills by viewModel.allBills.collectAsState(initial = emptyList())
    val coroutineScope = rememberCoroutineScope()

    var selectedDate by remember { mutableStateOf(LocalDate.now().withDayOfMonth(1)) }
    var showMonthPicker by remember { mutableStateOf(false) }

    val primaryColor = MaterialTheme.colorScheme.primary
    val errorColor = MaterialTheme.colorScheme.error
    val surfaceColor = MaterialTheme.colorScheme.surface
    val primaryContainer = MaterialTheme.colorScheme.primaryContainer
    val onPrimaryContainer = MaterialTheme.colorScheme.onPrimaryContainer

    val monthsList = remember {
        (0..120).map { LocalDate.now().withDayOfMonth(1).minusMonths(it.toLong()) }
    }

    val lazyListState = rememberLazyListState()

    // Sync selected date from scroll when user stops scrolling
    LaunchedEffect(lazyListState.isScrollInProgress) {
        if (!lazyListState.isScrollInProgress) {
            // Check offset to snap to the closest item more intuitively
            val layoutInfo = lazyListState.layoutInfo
            val visibleItems = layoutInfo.visibleItemsInfo
            if (visibleItems.isNotEmpty()) {
                val center = layoutInfo.viewportStartOffset + (layoutInfo.viewportEndOffset - layoutInfo.viewportStartOffset) / 2
                val closestItem = visibleItems.minByOrNull { Math.abs((it.offset + it.size / 2) - center) }
                if (closestItem != null) {
                    val index = closestItem.index
                    if (index in monthsList.indices) {
                        val snappedMonth = monthsList[index]
                        if (selectedDate != snappedMonth) {
                            selectedDate = snappedMonth
                        }
                    }
                }
            }
        }
    }

    // Scroll to new selected date when changed from dialog
    LaunchedEffect(selectedDate) {
        val targetIndex = monthsList.indexOf(selectedDate)
        if (targetIndex >= 0 && targetIndex != lazyListState.firstVisibleItemIndex) {
            lazyListState.animateScrollToItem(targetIndex)
        }
    }

    Shared_MonthYearPickerDialog(
        visible = showMonthPicker,
        currentMonth = selectedDate,
        onConfirm = { newDate ->
            selectedDate = newDate
            showMonthPicker = false
        },
        onDismiss = { showMonthPicker = false }
    )

    // Data filtering
    val currentMonthBills = remember(selectedDate, allBills) {
        allBills.filter {
            val date =
                Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault()).toLocalDate()
            date.year == selectedDate.year && date.monthValue == selectedDate.monthValue
        }
    }

    val monthExpense = currentMonthBills.filter { it.type == BillType.EXPENSE }.sumOf { it.amount }
    val monthIncome = currentMonthBills.filter { it.type == BillType.INCOME }.sumOf { it.amount }
    val monthBalance = monthIncome - monthExpense

    val chartData = remember(selectedDate, currentMonthBills) {
        val daysInMonth = selectedDate.lengthOfMonth()
        (1..daysInMonth).map { day ->
            val dailyExpense = currentMonthBills.filter {
                Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault())
                    .toLocalDate().dayOfMonth == day && it.type == BillType.EXPENSE
            }.sumOf { it.amount }

            val dailyIncome = currentMonthBills.filter {
                Instant.ofEpochMilli(it.createdAt).atZone(ZoneId.systemDefault())
                    .toLocalDate().dayOfMonth == day && it.type == BillType.INCOME
            }.sumOf { it.amount }

            val labelStr = if (day % 3 == 0 || day == 1) day.toString() else ""

            Bars(
                label = labelStr,
                values = listOf(
                    Bars.Data(label = "支出", value = dailyExpense, color = SolidColor(errorColor)),
                    Bars.Data(label = "收入", value = dailyIncome, color = SolidColor(primaryColor))
                )
            )
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(surfaceColor)
            .padding(vertical = 16.dp)
    ) {
        // Year and Month Snapper Header
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = "${selectedDate.year}",
                fontSize = 20.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier
                    .clickable { showMonthPicker = true }
                    .padding(end = 16.dp)
            )

            LazyRow(
                state = lazyListState,
                flingBehavior = rememberSnapFlingBehavior(lazyListState),
                horizontalArrangement = Arrangement.spacedBy(24.dp),
                contentPadding = PaddingValues(horizontal = 64.dp),
                modifier = Modifier.weight(1f)
            ) {
                itemsIndexed(monthsList) { index, monthDate ->
                    val isSelected = selectedDate == monthDate
                    val todayM = LocalDate.now().withDayOfMonth(1)
                    val titleStr = when (monthDate) {
                        todayM -> "本月"
                        todayM.minusMonths(1) -> "上月"
                        else -> "${monthDate.monthValue}月"
                    }

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        modifier = Modifier
                            .clickable {
                                coroutineScope.launch {
                                    lazyListState.animateScrollToItem(index)
                                }
                            }
                    ) {
                        Text(
                            text = titleStr,
                            color = if (isSelected) primaryColor else Color.Gray,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                            fontSize = 13.sp
                        )
                        if (isSelected) {
                            Icon(
                                imageVector = Icons.Default.ArrowDropUp,
                                contentDescription = null,
                                tint = primaryColor,
                                modifier = Modifier.size(48.dp)
                            )
                        } else {
                            Spacer(modifier = Modifier.height(24.dp))
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Summary Card
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(containerColor = primaryContainer)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "月支出",
                            color = onPrimaryContainer.copy(alpha = 0.8f),
                            fontSize = 14.sp
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = String.format(Locale.getDefault(), "%.2f", monthExpense),
                            color = onPrimaryContainer,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "月收入",
                            color = onPrimaryContainer.copy(alpha = 0.8f),
                            fontSize = 14.sp
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = String.format(Locale.getDefault(), "%.2f", monthIncome),
                            color = onPrimaryContainer,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "月结余",
                            color = onPrimaryContainer.copy(alpha = 0.8f),
                            fontSize = 14.sp
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = String.format(Locale.getDefault(), "%.2f", monthBalance),
                            color = onPrimaryContainer,
                            fontSize = 20.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(24.dp))

        // Chart Header
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(text = "收支统计", fontSize = 18.sp, fontWeight = FontWeight.Bold)
        }

        Spacer(modifier = Modifier.height(16.dp))

        // Chart
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(260.dp)
                .padding(horizontal = 16.dp)
        ) {
            ColumnChart(
                modifier = Modifier.fillMaxSize(),
                data = chartData,
                barProperties = BarProperties(
                    spacing = 2.dp,
                    cornerRadius = Bars.Data.Radius.Rectangle(topRight = 4.dp, topLeft = 4.dp),
                    thickness = 4.dp
                ),
                labelHelperProperties = LabelHelperProperties(
                    enabled = true,
                    textStyle = androidx.compose.ui.text.TextStyle(fontSize = 10.sp)
                ),
                indicatorProperties = ir.ehsannarmani.compose_charts.models.IndicatorProperties(
                    textStyle = androidx.compose.ui.text.TextStyle(fontSize = 10.sp)
                ),
                gridProperties = GridProperties(
                    xAxisProperties = GridProperties.AxisProperties(enabled = false),
                    yAxisProperties = GridProperties.AxisProperties(
                        enabled = true, color = SolidColor(
                            Color.LightGray.copy(alpha = 0.5f)
                        )
                    )
                ),
                animationSpec = spring(
                    dampingRatio = Spring.DampingRatioMediumBouncy,
                    stiffness = Spring.StiffnessLow
                )
            )
        }
    }
}
